-- Coach's personal training program: an 8-week hypertrophy block (2 lower-body +
-- 2 upper-body days/week) so Jon can log his own workouts through the coach login
-- instead of needing a separate client account. Structure mirrors the same
-- weeks -> days -> exercises jsonb shape every other program uses (see
-- 0001_schema.sql), so it plays back through the exact same ProgramLogger
-- component clients use.
--
-- Idempotent: safe to run more than once. Finds the (single) active coach profile,
-- inserts the program only if a program with this name isn't already attached to
-- that coach, and only sets profiles.program_id if the coach doesn't already have
-- a program assigned (never clobbers an existing assignment).
do $$
declare
  v_coach_id uuid;
  v_program_id uuid;
begin
  select id into v_coach_id
  from profiles
  where role = 'coach' and is_active = true
  order by created_at asc
  limit 1;

  if v_coach_id is null then
    raise notice 'No active coach profile found -- skipping personal program seed.';
    return;
  end if;

  select id into v_program_id
  from programs
  where client_id = v_coach_id and name = 'Coach Hypertrophy -- Legs & Upper (8-Week)';

  if v_program_id is null then
    insert into programs (goal, name, description, structure, is_template, is_default_template, client_id)
    values (
      'strength_gain',
      'Coach Hypertrophy -- Legs & Upper (8-Week)',
      '8-week hypertrophy block, 4 days/week (2 lower + 2 upper) built to add real quad/glute/hamstring tissue rather than chase weekly strength PRs. Lower days follow Meadows-style logic: activation -> heavy work -> pump work -> stretch/lengthened work. Progression rule: within a prescribed rep range, add a rep per set each week before adding load (e.g. 10/9/8 -> 11/10/9 -> 12/11/10 -> 12/12/12, then increase the load and restart the climb). Phases: Weeks 1-2 Establish (~2 RIR), Weeks 3-4 Push (1-2 RIR, final sets 0-1 RIR), Weeks 5-6 Mountain Dog (added intensity techniques on select lifts), Week 7 Overreach (hardest week, isolation work to 0 RIR), Week 8 Deload (-50% volume, 3-4 RIR, no intensity techniques).',
      '{"weeks": [{"week": 1, "note": "Weeks 1-2: Establish. Most sets ~2 RIR. Priorities: dial in exercise setup, find real working weights, learn where you actually feel each movement. Progression rule example for a 3x8-12 lift: aim for 10/9/8 reps this week.", "days": [{"day": 1, "label": "Day 1 \u2014 Quads + Adductors", "exercises": [{"name": "Seated Leg Curl", "sets": 4, "reps": "10-15", "rest": "90 sec", "notes": "Ramp the weight up each set. Final set: 10-12 full reps, then 5-8 partials, then a 10-second squeeze on the last rep. Warms up the knees/hamstrings before squatting."}, {"name": "Hack Squat", "sets": 4, "reps": "6-10", "rest": "3 min", "notes": "Heavy movement of the day. Feet relatively low, controlled eccentric, knees traveling forward, torso planted. No hack squat available -> use heel-elevated Smith squats instead."}, {"name": "Bulgarian Split Squat", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Slightly shorter stride for quad bias. Rest between legs if needed -- this is a hypertrophy set, not a conditioning circuit."}, {"name": "Leg Press", "sets": 3, "reps": "12-15", "rest": "2 min", "notes": "Controlled depth. Final set: 15 reps, rest 20 sec, 6-8 reps, rest 20 sec, 4-6 reps."}, {"name": "Leg Extension", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Final set: 10 full reps, then 10 partials from the stretched half, then a 10-second contraction."}, {"name": "Adductor Machine", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Not decorative inner-thigh work -- strong adductors add real size to the legs."}, {"name": "Standing Calf Raise", "sets": 4, "reps": "8-12", "rest": "60 sec", "notes": "2-3 second stretch at the bottom on every rep."}]}, {"day": 2, "label": "Day 2 \u2014 Chest + Back", "exercises": [{"name": "Incline DB Press", "sets": 3, "reps": "6-10", "rest": "2 min", "notes": ""}, {"name": "Machine Chest Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Fly", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}, {"name": "Chest-Supported Row", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Neutral-Grip Pulldown", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Meadows Row", "sets": 3, "reps": "10-12 each side", "rest": "90 sec", "notes": ""}, {"name": "Straight-Arm Pulldown", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}]}, {"day": 4, "label": "Day 4 \u2014 Hamstrings + Glutes", "exercises": [{"name": "Lying Leg Curl", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": "Progressively heavier sets. Final set: 8-10 reps, drop weight ~25%, another 8-10, drop again, 8-12 more."}, {"name": "Romanian Deadlift", "sets": 3, "reps": "6-10", "rest": "2-3 min", "notes": "Bodybuilding RDLs, not disguised max-attempt deadlifts. Hips back -> hamstring stretch -> stop -> drive hips forward. No touching the floor between reps. Keep this one as straight sets always -- no intensity techniques, even in the brutal weeks."}, {"name": "Glute-Biased Leg Press", "sets": 3, "reps": "10-15", "rest": "2 min", "notes": "Feet higher, slightly wider, toes slightly out. Deep, controlled eccentric."}, {"name": "Reverse Lunge", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Longer stride -- let the hip travel back."}, {"name": "45-Degree Back Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": "Glute emphasis: slightly rounded upper back, hips into the pad, squeeze the glutes. Do not hyperextend the lumbar spine."}, {"name": "Seated Leg Curl", "sets": 3, "reps": "12-15", "rest": "90 sec", "notes": "Final set: 10-15 reps plus 10 partials from the stretched position."}, {"name": "Seated Calf Raise", "sets": 4, "reps": "10-15", "rest": "60 sec", "notes": "2-3 second stretch at the bottom."}]}, {"day": 5, "label": "Day 5 \u2014 Shoulders + Arms + Back", "exercises": [{"name": "Machine Shoulder Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Lateral Raise", "sets": 4, "reps": "12-20", "rest": "60 sec", "notes": ""}, {"name": "Rear-Delt Fly", "sets": 4, "reps": "15-25", "rest": "45 sec", "notes": "High volume on purpose -- rear delts respond to reps, not ego load."}, {"name": "Assisted/Chest-Supported Pull-Up", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "One-Arm Cable Row", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "EZ-Bar Curl", "sets": 3, "reps": "8-12", "rest": "60 sec", "notes": ""}, {"name": "Hammer Curl", "sets": 2, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Rope Pressdown", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Overhead Cable Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}]}]}, {"week": 2, "note": "Weeks 1-2: Establish. Most sets ~2 RIR. Add a rep per set vs. last week before adding any load (e.g. 11/10/9).", "days": [{"day": 1, "label": "Day 1 \u2014 Quads + Adductors", "exercises": [{"name": "Seated Leg Curl", "sets": 4, "reps": "10-15", "rest": "90 sec", "notes": "Ramp the weight up each set. Final set: 10-12 full reps, then 5-8 partials, then a 10-second squeeze on the last rep. Warms up the knees/hamstrings before squatting."}, {"name": "Hack Squat", "sets": 4, "reps": "6-10", "rest": "3 min", "notes": "Heavy movement of the day. Feet relatively low, controlled eccentric, knees traveling forward, torso planted. No hack squat available -> use heel-elevated Smith squats instead."}, {"name": "Bulgarian Split Squat", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Slightly shorter stride for quad bias. Rest between legs if needed -- this is a hypertrophy set, not a conditioning circuit."}, {"name": "Leg Press", "sets": 3, "reps": "12-15", "rest": "2 min", "notes": "Controlled depth. Final set: 15 reps, rest 20 sec, 6-8 reps, rest 20 sec, 4-6 reps."}, {"name": "Leg Extension", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Final set: 10 full reps, then 10 partials from the stretched half, then a 10-second contraction."}, {"name": "Adductor Machine", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Not decorative inner-thigh work -- strong adductors add real size to the legs."}, {"name": "Standing Calf Raise", "sets": 4, "reps": "8-12", "rest": "60 sec", "notes": "2-3 second stretch at the bottom on every rep."}]}, {"day": 2, "label": "Day 2 \u2014 Chest + Back", "exercises": [{"name": "Incline DB Press", "sets": 3, "reps": "6-10", "rest": "2 min", "notes": ""}, {"name": "Machine Chest Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Fly", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}, {"name": "Chest-Supported Row", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Neutral-Grip Pulldown", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Meadows Row", "sets": 3, "reps": "10-12 each side", "rest": "90 sec", "notes": ""}, {"name": "Straight-Arm Pulldown", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}]}, {"day": 4, "label": "Day 4 \u2014 Hamstrings + Glutes", "exercises": [{"name": "Lying Leg Curl", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": "Progressively heavier sets. Final set: 8-10 reps, drop weight ~25%, another 8-10, drop again, 8-12 more."}, {"name": "Romanian Deadlift", "sets": 3, "reps": "6-10", "rest": "2-3 min", "notes": "Bodybuilding RDLs, not disguised max-attempt deadlifts. Hips back -> hamstring stretch -> stop -> drive hips forward. No touching the floor between reps. Keep this one as straight sets always -- no intensity techniques, even in the brutal weeks."}, {"name": "Glute-Biased Leg Press", "sets": 3, "reps": "10-15", "rest": "2 min", "notes": "Feet higher, slightly wider, toes slightly out. Deep, controlled eccentric."}, {"name": "Reverse Lunge", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Longer stride -- let the hip travel back."}, {"name": "45-Degree Back Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": "Glute emphasis: slightly rounded upper back, hips into the pad, squeeze the glutes. Do not hyperextend the lumbar spine."}, {"name": "Seated Leg Curl", "sets": 3, "reps": "12-15", "rest": "90 sec", "notes": "Final set: 10-15 reps plus 10 partials from the stretched position."}, {"name": "Seated Calf Raise", "sets": 4, "reps": "10-15", "rest": "60 sec", "notes": "2-3 second stretch at the bottom."}]}, {"day": 5, "label": "Day 5 \u2014 Shoulders + Arms + Back", "exercises": [{"name": "Machine Shoulder Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Lateral Raise", "sets": 4, "reps": "12-20", "rest": "60 sec", "notes": ""}, {"name": "Rear-Delt Fly", "sets": 4, "reps": "15-25", "rest": "45 sec", "notes": "High volume on purpose -- rear delts respond to reps, not ego load."}, {"name": "Assisted/Chest-Supported Pull-Up", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "One-Arm Cable Row", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "EZ-Bar Curl", "sets": 3, "reps": "8-12", "rest": "60 sec", "notes": ""}, {"name": "Hammer Curl", "sets": 2, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Rope Pressdown", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Overhead Cable Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}]}]}, {"week": 3, "note": "Weeks 3-4: Push. Most sets 1-2 RIR; final set of key movements 0-1 RIR. Once every set in the rep range hits (e.g. 12/11/10), add 5-10 lb or 1-2 reps next time out.", "days": [{"day": 1, "label": "Day 1 \u2014 Quads + Adductors", "exercises": [{"name": "Seated Leg Curl", "sets": 4, "reps": "10-15", "rest": "90 sec", "notes": "Ramp the weight up each set. Final set: 10-12 full reps, then 5-8 partials, then a 10-second squeeze on the last rep. Warms up the knees/hamstrings before squatting."}, {"name": "Hack Squat", "sets": 4, "reps": "6-10", "rest": "3 min", "notes": "Heavy movement of the day. Feet relatively low, controlled eccentric, knees traveling forward, torso planted. No hack squat available -> use heel-elevated Smith squats instead."}, {"name": "Bulgarian Split Squat", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Slightly shorter stride for quad bias. Rest between legs if needed -- this is a hypertrophy set, not a conditioning circuit."}, {"name": "Leg Press", "sets": 3, "reps": "12-15", "rest": "2 min", "notes": "Controlled depth. Final set: 15 reps, rest 20 sec, 6-8 reps, rest 20 sec, 4-6 reps."}, {"name": "Leg Extension", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Final set: 10 full reps, then 10 partials from the stretched half, then a 10-second contraction."}, {"name": "Adductor Machine", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Not decorative inner-thigh work -- strong adductors add real size to the legs."}, {"name": "Standing Calf Raise", "sets": 4, "reps": "8-12", "rest": "60 sec", "notes": "2-3 second stretch at the bottom on every rep."}]}, {"day": 2, "label": "Day 2 \u2014 Chest + Back", "exercises": [{"name": "Incline DB Press", "sets": 3, "reps": "6-10", "rest": "2 min", "notes": ""}, {"name": "Machine Chest Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Fly", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}, {"name": "Chest-Supported Row", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Neutral-Grip Pulldown", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Meadows Row", "sets": 3, "reps": "10-12 each side", "rest": "90 sec", "notes": ""}, {"name": "Straight-Arm Pulldown", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}]}, {"day": 4, "label": "Day 4 \u2014 Hamstrings + Glutes", "exercises": [{"name": "Lying Leg Curl", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": "Progressively heavier sets. Final set: 8-10 reps, drop weight ~25%, another 8-10, drop again, 8-12 more."}, {"name": "Romanian Deadlift", "sets": 3, "reps": "6-10", "rest": "2-3 min", "notes": "Bodybuilding RDLs, not disguised max-attempt deadlifts. Hips back -> hamstring stretch -> stop -> drive hips forward. No touching the floor between reps. Keep this one as straight sets always -- no intensity techniques, even in the brutal weeks."}, {"name": "Glute-Biased Leg Press", "sets": 3, "reps": "10-15", "rest": "2 min", "notes": "Feet higher, slightly wider, toes slightly out. Deep, controlled eccentric."}, {"name": "Reverse Lunge", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Longer stride -- let the hip travel back."}, {"name": "45-Degree Back Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": "Glute emphasis: slightly rounded upper back, hips into the pad, squeeze the glutes. Do not hyperextend the lumbar spine."}, {"name": "Seated Leg Curl", "sets": 3, "reps": "12-15", "rest": "90 sec", "notes": "Final set: 10-15 reps plus 10 partials from the stretched position."}, {"name": "Seated Calf Raise", "sets": 4, "reps": "10-15", "rest": "60 sec", "notes": "2-3 second stretch at the bottom."}]}, {"day": 5, "label": "Day 5 \u2014 Shoulders + Arms + Back", "exercises": [{"name": "Machine Shoulder Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Lateral Raise", "sets": 4, "reps": "12-20", "rest": "60 sec", "notes": ""}, {"name": "Rear-Delt Fly", "sets": 4, "reps": "15-25", "rest": "45 sec", "notes": "High volume on purpose -- rear delts respond to reps, not ego load."}, {"name": "Assisted/Chest-Supported Pull-Up", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "One-Arm Cable Row", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "EZ-Bar Curl", "sets": 3, "reps": "8-12", "rest": "60 sec", "notes": ""}, {"name": "Hammer Curl", "sets": 2, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Rope Pressdown", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Overhead Cable Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}]}]}, {"week": 4, "note": "Weeks 3-4: Push. Keep attacking final working sets at 0-1 RIR. Once all sets hit the top of the range (12/12/12), bump the load and restart the rep climb at that new weight.", "days": [{"day": 1, "label": "Day 1 \u2014 Quads + Adductors", "exercises": [{"name": "Seated Leg Curl", "sets": 4, "reps": "10-15", "rest": "90 sec", "notes": "Ramp the weight up each set. Final set: 10-12 full reps, then 5-8 partials, then a 10-second squeeze on the last rep. Warms up the knees/hamstrings before squatting."}, {"name": "Hack Squat", "sets": 4, "reps": "6-10", "rest": "3 min", "notes": "Heavy movement of the day. Feet relatively low, controlled eccentric, knees traveling forward, torso planted. No hack squat available -> use heel-elevated Smith squats instead."}, {"name": "Bulgarian Split Squat", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Slightly shorter stride for quad bias. Rest between legs if needed -- this is a hypertrophy set, not a conditioning circuit."}, {"name": "Leg Press", "sets": 3, "reps": "12-15", "rest": "2 min", "notes": "Controlled depth. Final set: 15 reps, rest 20 sec, 6-8 reps, rest 20 sec, 4-6 reps."}, {"name": "Leg Extension", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Final set: 10 full reps, then 10 partials from the stretched half, then a 10-second contraction."}, {"name": "Adductor Machine", "sets": 3, "reps": "12-20", "rest": "60 sec", "notes": "Not decorative inner-thigh work -- strong adductors add real size to the legs."}, {"name": "Standing Calf Raise", "sets": 4, "reps": "8-12", "rest": "60 sec", "notes": "2-3 second stretch at the bottom on every rep."}]}, {"day": 2, "label": "Day 2 \u2014 Chest + Back", "exercises": [{"name": "Incline DB Press", "sets": 3, "reps": "6-10", "rest": "2 min", "notes": ""}, {"name": "Machine Chest Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Fly", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}, {"name": "Chest-Supported Row", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Neutral-Grip Pulldown", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Meadows Row", "sets": 3, "reps": "10-12 each side", "rest": "90 sec", "notes": ""}, {"name": "Straight-Arm Pulldown", "sets": 2, "reps": "12-15", "rest": "60 sec", "notes": ""}]}, {"day": 4, "label": "Day 4 \u2014 Hamstrings + Glutes", "exercises": [{"name": "Lying Leg Curl", "sets": 4, "reps": "8-12", "rest": "90 sec", "notes": "Progressively heavier sets. Final set: 8-10 reps, drop weight ~25%, another 8-10, drop again, 8-12 more."}, {"name": "Romanian Deadlift", "sets": 3, "reps": "6-10", "rest": "2-3 min", "notes": "Bodybuilding RDLs, not disguised max-attempt deadlifts. Hips back -> hamstring stretch -> stop -> drive hips forward. No touching the floor between reps. Keep this one as straight sets always -- no intensity techniques, even in the brutal weeks."}, {"name": "Glute-Biased Leg Press", "sets": 3, "reps": "10-15", "rest": "2 min", "notes": "Feet higher, slightly wider, toes slightly out. Deep, controlled eccentric."}, {"name": "Reverse Lunge", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Longer stride -- let the hip travel back."}, {"name": "45-Degree Back Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": "Glute emphasis: slightly rounded upper back, hips into the pad, squeeze the glutes. Do not hyperextend the lumbar spine."}, {"name": "Seated Leg Curl", "sets": 3, "reps": "12-15", "rest": "90 sec", "notes": "Final set: 10-15 reps plus 10 partials from the stretched position."}, {"name": "Seated Calf Raise", "sets": 4, "reps": "10-15", "rest": "60 sec", "notes": "2-3 second stretch at the bottom."}]}, {"day": 5, "label": "Day 5 \u2014 Shoulders + Arms + Back", "exercises": [{"name": "Machine Shoulder Press", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "Cable Lateral Raise", "sets": 4, "reps": "12-20", "rest": "60 sec", "notes": ""}, {"name": "Rear-Delt Fly", "sets": 4, "reps": "15-25", "rest": "45 sec", "notes": "High volume on purpose -- rear delts respond to reps, not ego load."}, {"name": "Assisted/Chest-Supported Pull-Up", "sets": 3, "reps": "8-12", "rest": "90 sec", "notes": ""}, {"name": "One-Arm Cable Row", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "EZ-Bar Curl", "sets": 3, "reps": "8-12", "rest": "60 sec", "notes": ""}, {"name": "Hammer Curl", "sets": 2, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Rope Pressdown", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}, {"name": "Overhead Cable Extension", "sets": 3, "reps": "10-15", "rest": "60 sec", "notes": ""}]}]}, {"week": 5, "note": "Weeks 5-6: Mountain Dog territory -- more brutality, applied intelligently, not to every exercise. Hack squat final set uses 1.5 reps (down, halfway up, down, full rep) for 6-8 reps; leg extensions add partials to the final set; leg curls get a drop set. Romanian deadlifts stay straight sets -- no intensity techniques on that lift, ever.", "days": [{"day": 1, "label": "Day 1 \u2014 Quads + Adductors", "exercises": [{"name": "Seated Leg Curl", "sets": 4, "reps": "10-15", "rest": "90 sec", "notes": "Ramp the weight up each set. Final set: 10-12 full reps, then 5-8 partials, then a 10-second squeeze on the last rep. Warms up the knees/hamstrings before squatting."}, {"name": "Hack Squat", "sets": 4, "reps": "6-10", "rest": "3 min", "notes": "Heavy movement of the day. Feet relatively low, controlled eccentric, knees traveling forward, torso planted. No hack squat available -> use heel-elevated Smith squats instead."}, {"name": "Bulgarian Split Squat", "sets": 3, "reps": "8-12 each leg", "rest": "90 sec", "notes": "Slightly shorter stride for quad bias. Rest between legs if needed -- this is a hypertrop